//! Independent conservation, fractional rewards and selected manual World actions.
use gielinor_world::{assembly::{Job,Recipe,PreciseRecipe,Outcome},inventory::{Inventory,Item,StackType,Catalog},stats::Stats,npc::RandomSource,simulation::{World,PlayerData,ActorId,WorldEvent,Action},held_use::{Handler,Scope,Type,Request},CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("deterministic assembly drew RNG")}}
fn recipe(i:usize)->PreciseRecipe{let(orb,out,level,xp,spot)=[(571,1395,54,1000,1370),(575,1399,58,1125,1371),(569,1393,62,1250,1372),(573,1397,66,1375,306)][i];PreciseRecipe{recipe:Recipe{first:1391,second:orb,output:out,skill:12,level,base_xp:0,members:true},xp_tenths:xp,ticks:2,animation:Some(7531),spot:Some(spot)}}
fn fixture(i:usize,current:i8)->(Inventory,Stats){let r=recipe(i);let mut inv=Inventory::new(28,StackType::Normal,false);for s in 0..28{inv.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for(s,id)in[(5,1391),(23,1391),(19,r.recipe.second),(21,r.recipe.second),(27,995)]{inv.restore_slot(s,Some(Item{id,count:if id==995{1000}else{1},vars:0})).unwrap();}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,current);stats.set_fine_xp(12,130344311).unwrap();(inv,stats)}
fn expected(inv:&Inventory,r:PreciseRecipe)->Inventory{let mut inv=inv.clone();inv.restore_slot(5,Some(Item{id:r.recipe.output,count:1,vars:0})).unwrap();inv.restore_slot(19,None).unwrap();inv}
fn world(i:usize,current:i8,member:bool,rate:i32,reverse:bool)->(World,ActorId,Request){let r=recipe(i);let(inv,stats)=fixture(i,current);let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent orb attachment".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.inventory=inv;d.xp_rate_hundreds=rate;w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();for id in[1391,r.recipe.second]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1391,r.recipe.second,Handler::AssemblyPrecise(r)).unwrap();w.drain_events();let h=if reverse{Request{selected_slot:19,selected_id:r.recipe.second,target_slot:5,target_id:1391}}else{Request{selected_slot:5,selected_id:1391,target_slot:19,target_id:r.recipe.second}};(w,a,h)}
#[test]
fn ninety_six_precise_transactions_preserve_fractional_xp_and_whole_state(){let mut n=0;for i in 0..4{let r=recipe(i);for current in[r.recipe.level as i8-1,r.recipe.level as i8,99]{for member in[false,true]{for rate in[0,100,125,500]{let(mut inv,mut stats)=fixture(i,current);let before=(inv.clone(),stats.clone());let job=Job{recipe:r.recipe,first_slot:5,second_slot:19};let(result,advanced)=job.complete_awarding_tenths(&mut inv,&Catalog::default(),&mut stats,rate,member,r.xp_tenths);let good=member && current>=r.recipe.level as i8 && rate>0;if good{assert_eq!(result,Outcome::Made);assert!(advanced.is_some());let mut xp=before.1.clone();xp.set_fine_xp(12,130344311+i32::from(r.xp_tenths)*rate/100).unwrap();assert_eq!(inv,expected(&before.0,r));assert_eq!(stats,xp);}else{assert_ne!(result,Outcome::Made);assert!(advanced.is_none());assert_eq!((inv,stats),before);}n+=1;}}}}assert_eq!(n,96);}
#[test]
fn one_hundred_ninety_two_real_world_routes_have_two_tick_manual_credit_and_no_repeat(){let mut n=0;for i in 0..4{let r=recipe(i);for current in[r.recipe.level as i8-1,r.recipe.level as i8,99]{for member in[false,true]{for rate in[0,100,125,500]{for reverse in[false,true]{let(mut w,a,h)=world(i,current,member,rate,reverse);let before=w.data(a).unwrap().clone();let admitted=member && current>=r.recipe.level as i8;let good=admitted && rate>0;w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();assert!(w.take_tool_crafting_request(a).unwrap().is_none());for _ in 0..2{w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);}w.tick_with_random(&mut NoDraw).unwrap();let mut inv=before.inventory.clone();let mut stats=before.stats.clone();if good{inv=expected(&inv,r);stats.set_fine_xp(12,130344311+i32::from(r.xp_tenths)*rate/100).unwrap();assert!(w.finish_held_use(a,h).is_err());}for _ in 0..8{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,inv);assert_eq!(w.data(a).unwrap().stats,stats);let events=w.drain_events();assert_eq!(events.iter().filter(|e|matches!(e,WorldEvent::SkillAdvanced{..})).count(),usize::from(good));assert_eq!(events.iter().filter(|e|matches!(e,WorldEvent::PlayerCombatAnimation{sequence:7531,..})).count(),usize::from(admitted));assert_eq!(events.iter().filter(|e|matches!(e,WorldEvent::PlayerSpotAnimation{spot,..}if Some(*spot)==r.spot)).count(),usize::from(admitted));n+=1;}}}}}assert_eq!(n,192);}
#[test]
fn eighty_eight_late_changes_refuse_without_fallback_to_duplicate_inputs(){let mut n=0;for i in 0..4{for reverse in[false,true]{for mode in 0..11{let r=recipe(i);let(mut w,a,h)=world(i,99,true,125,reverse);w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();match mode{0=>w.data_mut(a).unwrap().inventory.restore_slot(5,None).unwrap(),1=>w.data_mut(a).unwrap().inventory.restore_slot(19,None).unwrap(),2=>w.data_mut(a).unwrap().inventory.restore_slot(19,Some(Item{id:r.recipe.second,count:1,vars:1})).unwrap(),3=>w.data_mut(a).unwrap().inventory.restore_slot(5,Some(Item{id:1391,count:1,vars:1})).unwrap(),4=>w.set_membership(a,false).unwrap(),5=>w.data_mut(a).unwrap().stats.set_current(12,r.recipe.level as i8-1),6=>w.data_mut(a).unwrap().xp_rate_hundreds=0,7=>{w.object_types.dummy.insert(r.recipe.output);},8=>w.submit(a,Action::Walk{destination:CoordGrid::new(3201,3200,0).unwrap(),run:false}).unwrap(),9=>{w.close_dialogs(a).unwrap();},_=>w.request_logout(a).unwrap()};let before=w.data(a).unwrap().clone();for _ in 0..10{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"profile{i} mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats,"profile{i} mode{mode}");n+=1;}}}assert_eq!(n,88);}
